mapper.select:
select ex.Ex_Name as exName, ex.Ex_Id_Type as exIdType, ex.Ex_Id_Number as exIdNumber, ex.year as year, mn.* from Sec_Expert_Pause mn left join Sec_Expert ex on mn.Ex_Id=ex.Ex_Id
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc

mapper.sql:
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.Ex_Id = #{params.exId}


    and mn.State=#{params.state}


    and INSTR(mn.Create_Uname,#{params.createUname})


    and INSTR(ex.Ex_Name,#{params.exName})


    and ex.Ex_Applicant_Id = #{params.exApplicantId}


    and ex.year = #{params.year}


    and mn.Sep_Days_Year = #{params.sepDaysYear}


    and mn.State in
    
        #{state}
    


    and mn.Sep_Days_Year >= #{params.sepDaysYearStart}


    and mn.Sep_Days_Year <= #{params.sepDaysYearEnd}


    and mn.Sep_Start_Time >= #{params.sepStartTimeStart}


    and mn.Sep_Start_Time <= #{params.sepStartTimeEnd}


    and mn.Sep_End_Time >= #{params.sepEndTimeStart}


    and mn.Sep_End_Time <= #{params.sepEndTimeEnd}


    and mn.Create_Time >= #{params.createTimeStart}


    and mn.Create_Time <= #{params.createTimeEnd}


    and ex.Ex_Name in
    
        #{exName}
    


    and ex.year in
    
        #{year}

mapper.select:
select distinct
${selectClause}
from Sec_Expert_Pause mn
left join Sec_Expert ex on mn.Ex_Id=ex.Ex_Id


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc

select mn.*
from SYS_FileTemplate mn
where mn.T_Code = #{fileCode}
